import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from '@vercel/geistcn/components';
import type { JSX } from 'react';

export function Component(): JSX.Element {
  return (
    <ContextMenu>
      <ContextMenuTrigger>
        <div
          className="text-copy-14"
          style={{
            width: 300,
            padding: '45px 0',
            border: '1px var(--ds-gray-alpha-600) dashed',
            borderRadius: 4,
            textAlign: 'center',
          }}
        >
          Right click here
        </div>
      </ContextMenuTrigger>
      <ContextMenuContent>
        <ContextMenuItem
          onClick={(): void => console.log('value')}
          value="hello"
        >
          Item one
        </ContextMenuItem>
        <ContextMenuItem
          onClick={(): void => console.log('value')}
          value="hello"
        >
          Item Two
        </ContextMenuItem>
        <ContextMenuItem
          onClick={(): void => console.log('value')}
          value="hello"
        >
          Item Three
        </ContextMenuItem>
        <ContextMenuItem
          onClick={(): void => console.log('value')}
          value="hello"
        >
          Item Four
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

